SELECT        dbo.tblEbay_Consignments.ID, dbo.tblEbay_Consignments.AccountId, dbo.tblEbay_Consignments.EbayUserID, dbo.tblEbay_Consignments.CreatedDateUTC, dbo.tblEbay_Consignments.EmailAddress, 
                         dbo.tblEbay_Consignments.FirstName, dbo.tblEbay_Consignments.LastName, dbo.tblEbay_Consignments.B_CompanyName, dbo.tblEbay_Consignments.B_Address1, dbo.tblEbay_Consignments.B_Address2, 
                         dbo.tblEbay_Consignments.B_Town, dbo.tblEbay_Consignments.B_Postcode, dbo.tblEbay_Consignments.B_CountryCode, dbo.tblEbay_Consignments.B_RF, dbo.tblEbay_Consignments.B_TownNPostcode, 
                         dbo.tblEbay_Consignments.C_CompanyName, dbo.tblEbay_Consignments.C_Address1, dbo.tblEbay_Consignments.C_Address2, dbo.tblEbay_Consignments.C_Town, dbo.tblEbay_Consignments.C_Postcode, 
                         dbo.tblEbay_Consignments.C_CountryCode, dbo.tblEbay_Consignments.C_RF, dbo.tblEbay_Consignments.C_TownNPostcode, dbo.tblEbay_Consignments.Phoneno_Mobile, dbo.tblEbay_Consignments.Phoneno, 
                         dbo.tblEbay_Consignments.GST_Number, dbo.tblEbay_Consignments.SP_Instruction1, dbo.tblEbay_Consignments.SP_Instruction2, dbo.tblEbay_Consignments.SP_Instruction3, dbo.tblEbay_Consignments.Status, 
                         dbo.tblEbay_Consignments.PickupCSAID, dbo.tblEbay_Consignments.PickupCourierID, dbo.tblEbay_Consignments.PrintDateUTC, dbo.tblEbay_Consignments.OrderClosedDateUTC, dbo.tblEbay_Consignments.Do_NeedPickup, 
                         dbo.tblEbay_Consignments.NoOfItems, dbo.tblEbay_Consignments.P_Date, dbo.tblEbay_Consignments.P_Time, dbo.tblEbay_Consignments.TotalLabelCost, dbo.tblEbay_Consignments.TotalReplacementPckCost, 
                         dbo.tblEbay_Consignments.GSTRate, dbo.tblEbay_Consignments_Items.OrderID, dbo.tblEbay_Consignments_Items.LineItemID, dbo.tblEbay_Consignments_Items.Title, dbo.tblEbay_Consignments_Items.SKU, 
                         dbo.tblEbay_Consignments_Items.EbayCreateDate, dbo.tblEbay_Consignments_Items.TotalValue, dbo.tblEbay_Consignments_Items.DeliveryCompanyName, dbo.tblEbay_Consignments_Items.DeliveryName, 
                         dbo.tblEbay_Consignments_Items.DeliveryPhone, dbo.tblEbay_Consignments_Items.DeliveryStreet, dbo.tblEbay_Consignments_Items.DeliveryCity, dbo.tblEbay_Consignments_Items.DeliveryPostcode, 
                         dbo.tblEbay_Consignments_Items.DeliveryCountry, dbo.tblEbay_Consignments_Items.IsValidAddress, dbo.tblEbay_Consignments_Items.LabelCost, dbo.tblEbay_Consignments_Items.IsDeeded, 
                         dbo.tblEbay_Consignments_Items.IsSignatureRequired, dbo.tblEbay_Consignments_Items.ItemType, dbo.tblEbay_Consignments_Items.DeliveryRF, dbo.tblEbay_Consignments_Items.DeliveryStreet1, 
                         dbo.tblEbay_Consignments_Items.DeliveryPhone1, dbo.tblEbay_Consignments_Items.DeliveryEmail, dbo.tblEbay_Consignments_Items.SP_Instruction1 AS Delivery_SP1, 
                         dbo.tblEbay_Consignments_Items.SP_Instruction2 AS Delivery_SP2, dbo.tblEbay_Consignments_Items.SP_Instruction3 AS Delivery_SP3, dbo.tblEbay_Consignments_Items.GalleryURL, 
                         dbo.tblEbay_Consignments_Items.EbayViewURL, dbo.tblEbay_Consignments_Items.OrderClosedDateUTC AS ItemOrderClosedDateUTC, dbo.tblEbay_Consignments_Items.PrintDateUTC AS ItemPrintDateUTC, 
                         dbo.tblEbay_Consignments_Items.NoOfPrints, dbo.tblEbay_Consignments_Items_Labels.EbayConsignmentItemID, dbo.tblEbay_Consignments_Items_Labels.LabelCost AS ItemLabelCost, 
                         dbo.tblEbay_Consignments_Items_Labels.LabelNumber, dbo.tblEbay_Consignments_Items_Labels.PackageType, dbo.tblEbay_Consignments_Items_Labels.Prefix, dbo.tblEbay_Consignments_Items_Labels.LabelColour, 
                         dbo.tblEbay_Consignments_Items_Labels.Status AS ItemLabelStatus, dbo.tblEbay_Consignments.AdminStatus, dbo.tblEbay_Consignments_Items.AdminStatus AS ItemAdminStatus, 
                         dbo.tblEbay_Consignments_Items_Labels.AdminStatus AS ItemLabelAdminStatus, dbo.tblEbay_Consignments_Items_Labels.ID AS ItemLabelID, 
                         dbo.tblEbay_Consignments_Items_Labels.CreatedDateUTC AS ItemLabelCreateDateUTC, dbo.tblEbay_Consignments.CreateDateLocal
FROM            dbo.tblEbay_Consignments WITH (NOLOCK) INNER JOIN
                         dbo.tblEbay_Consignments_Items WITH (NOLOCK) ON dbo.tblEbay_Consignments.ID = dbo.tblEbay_Consignments_Items.EbayConsignmentID INNER JOIN
                         dbo.tblEbay_Consignments_Items_Labels WITH (NOLOCK) ON dbo.tblEbay_Consignments_Items.ID = dbo.tblEbay_Consignments_Items_Labels.EbayConsignmentItemID